CREATE TABLE IF NOT EXISTS task_status_history (id INTEGER PRIMARY KEY AUTOINCREMENT, task_id INTEGER NOT NULL REFERENCES tasks(id), from_status TEXT, to_status TEXT NOT NULL, changed_by INTEGER REFERENCES users(id), note TEXT, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS asset_condition_counts (id INTEGER PRIMARY KEY AUTOINCREMENT, asset_id INTEGER NOT NULL REFERENCES assets(id) ON DELETE CASCADE, condition TEXT NOT NULL, quantity INTEGER NOT NULL CHECK(quantity >= 0), UNIQUE(asset_id,condition));
CREATE TABLE IF NOT EXISTS software_installations (id INTEGER PRIMARY KEY AUTOINCREMENT, software_id INTEGER NOT NULL REFERENCES software(id), asset_id INTEGER NOT NULL REFERENCES assets(id), status TEXT NOT NULL, installed_at TEXT, target_remove_at TEXT, removed_at TEXT, pic_id INTEGER REFERENCES users(id), event_id INTEGER REFERENCES events(id), notes TEXT, UNIQUE(software_id,asset_id));
CREATE TABLE IF NOT EXISTS notifications (id INTEGER PRIMARY KEY AUTOINCREMENT, user_id INTEGER NOT NULL REFERENCES users(id), title TEXT NOT NULL, message TEXT NOT NULL, read_at TEXT, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS import_batches (id INTEGER PRIMARY KEY AUTOINCREMENT, source_name TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'preview', accepted_rows INTEGER NOT NULL DEFAULT 0, rejected_rows INTEGER NOT NULL DEFAULT 0, created_by INTEGER REFERENCES users(id), created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);

